// Companies that are hiring faster since last week, as one Slack message.
const rows = $input.all().map(i => i.json).filter(r => r.type === 'company_summary');
const growing = rows
  .filter(r => (r.netChange ?? 0) > 0)
  .sort((a, b) => b.netChange - a.netChange)
  .slice(0, 15)
  .map(r => `• *${r.company}*: ${r.openJobs} open (+${r.newJobs} new, -${r.closedJobs} closed) · top team: ${r.topDepartments?.[0]?.name ?? 'n/a'} · ${r.boardUrl}`);
const text = growing.length
  ? `:chart_with_upwards_trend: Hiring signals this week\n${growing.join('\n')}`
  : `No company in your watchlist added roles this week (${rows.length} checked).`;
return [{ json: { text } }];
